The returned function also contains two convenient helper methods:

* `cancel()` – clears any pending timeout, preventing an eventual call.
* `flush()` – forces `fn` to run immediately, ignoring the pending timeout.

```js
/**
 * Creates a debounced version of `fn`.
 *
 * @param {Function} fn      The function to debounce.
 * @param {number}   delay   Milliseconds to wait before invoking `fn`.
 * @param {boolean}  [immediate=false]
 *      If true, invoke at the start of the burst.
 *
 * @returns {Function} Debounced function with `cancel()` / `flush()` methods.
 */
function debounce(fn, delay, immediate = false) {
  let timeoutId = null;     // Current pending timer
  let lastArgs = null;      // Arguments for the *last* call
  let lastContext = null;   // `this` for the *last* call

  // The debounced wrapper
  function debounced(...args) {
    const context = this;
    lastArgs = args;
    lastContext = context;

    const invokeFunc = () => {
      timeoutId = null;
      if (!immediate) {
        fn.apply(lastContext, lastArgs);
        // Clean up references so we don't keep a stray closure alive
        lastArgs = lastContext = null;
      }
    };

    if (immediate && !timeoutId) {
      // First call in a burst – invoke right away
      fn.apply(context, args);
      lastArgs = lastContext = null;
    }

    // Reset the timer
    clearTimeout(timeoutId);
    timeoutId = setTimeout(invokeFunc, delay);
  }

  // Abort any pending execution
  debounced.cancel = () => {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
      lastArgs = lastContext = null;
    }
  };

  // Force execution immediately
  debounced.flush = () => {
    if (timeoutId) {
      clearTimeout(timeoutId);
      timeoutId = null;
      fn.apply(lastContext, lastArgs);
      lastArgs = lastContext = null;
    }
  };

  return debounced;
}
```

